package de.robv.android.xposed;import java.lang.reflect.*;import java.util.*;public class XposedBridge {public static Map<Method,XC_MethodHook> hooks=new HashMap<>();public static XC_MethodHook.Unhook hookMethod(Method m,XC_MethodHook h){hooks.put(m,h);return h.new Unhook();}public static Object[] dispatch(String n,Object[] a){for(Method m:hooks.keySet())if(m.getName().equals(n)){XC_MethodHook.MethodHookParam p=new XC_MethodHook.MethodHookParam();p.args=a;try{hooks.get(m).beforeHookedMethod(p);}catch(Throwable e){throw new RuntimeException(e);}return p.args;}return a;}}
